/* eslint-disable */
export const POSTGRES_SCHEMA = "-- KNIT — lược đồ cơ sở dữ liệu Postgres (Supabase).\n--\n-- Đây là bản Postgres của lược đồ SQLite trong `server/src/lib/db.ts`.\n-- Hai bản phải giữ cùng tên bảng/cột để lớp trừu hợp `server/src/lib/sql.ts`\n-- chạy được với cả hai backend mà không cần rẽ nhánh trong mã nghiệp vụ.\n--\n-- Áp dụng:\n--   - Qua Supabase CLI:  `supabase db push`\n--   - Hoặc dán vào SQL Editor trên dashboard supabase.com.\n\n-- ---------------------------------------------------------------------------\n-- Người dùng\n-- ---------------------------------------------------------------------------\nCREATE TABLE IF NOT EXISTS users (\n  id            TEXT PRIMARY KEY,\n  email         TEXT NOT NULL UNIQUE,\n  password_hash TEXT NOT NULL,\n  display_name  TEXT NOT NULL,\n  faculty_vi    TEXT NOT NULL,\n  faculty_en    TEXT NOT NULL,\n  cohort        TEXT NOT NULL,\n  role          TEXT NOT NULL CHECK (role IN ('student','contributor','staff','admin')),\n  verified      BOOLEAN NOT NULL DEFAULT FALSE,\n  avatar_seed   TEXT NOT NULL,\n  avatar_url    TEXT,\n  avatar_tone   TEXT NOT NULL DEFAULT 'brand',\n  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n\n-- ---------------------------------------------------------------------------\n-- Câu hỏi\n-- ---------------------------------------------------------------------------\nCREATE TABLE IF NOT EXISTS questions (\n  id           TEXT PRIMARY KEY,\n  title        TEXT NOT NULL,\n  title_en     TEXT NOT NULL,\n  body         TEXT NOT NULL,\n  body_en      TEXT NOT NULL,\n  topic        TEXT NOT NULL,\n  author_id    TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  also_need    INTEGER NOT NULL DEFAULT 0,\n  views        INTEGER NOT NULL DEFAULT 0,\n  anonymous    BOOLEAN NOT NULL DEFAULT FALSE,\n  tags         JSONB NOT NULL DEFAULT '[]'::jsonb\n);\n\n-- ---------------------------------------------------------------------------\n-- Câu trả lời (kèm biến thể ẩn danh và thông tin chuyển văn phòng)\n-- ---------------------------------------------------------------------------\nCREATE TABLE IF NOT EXISTS answers (\n  id                   TEXT PRIMARY KEY,\n  question_id          TEXT NOT NULL REFERENCES questions(id) ON DELETE CASCADE,\n  author_id            TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  body                 TEXT NOT NULL,\n  body_en              TEXT NOT NULL,\n  created_at           TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  accepted             BOOLEAN NOT NULL DEFAULT FALSE,\n  helpful_count        INTEGER NOT NULL DEFAULT 0,\n  -- biến thể \"Trường hợp của mình khác\"\n  variant_context      TEXT,\n  variant_context_en   TEXT,\n  variant_anonymous    BOOLEAN,\n  referral_office      TEXT,\n  referral_office_en   TEXT,\n  referral_note        TEXT,\n  referral_note_en     TEXT\n);\n\nCREATE TABLE IF NOT EXISTS answer_sources (\n  id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  answer_id  TEXT NOT NULL REFERENCES answers(id) ON DELETE CASCADE,\n  title      TEXT NOT NULL,\n  url        TEXT NOT NULL,\n  publisher  TEXT NOT NULL\n);\n\n-- ---------------------------------------------------------------------------\n-- Tương tác\n-- ---------------------------------------------------------------------------\nCREATE TABLE IF NOT EXISTS helpful_votes (\n  answer_id TEXT NOT NULL REFERENCES answers(id) ON DELETE CASCADE,\n  user_id   TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  PRIMARY KEY (answer_id, user_id)\n);\n\nCREATE TABLE IF NOT EXISTS also_need_votes (\n  question_id TEXT NOT NULL REFERENCES questions(id) ON DELETE CASCADE,\n  user_id     TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  PRIMARY KEY (question_id, user_id)\n);\n\nCREATE TABLE IF NOT EXISTS follows (\n  user_id     TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  question_id TEXT NOT NULL REFERENCES questions(id) ON DELETE CASCADE,\n  PRIMARY KEY (user_id, question_id)\n);\n\nCREATE TABLE IF NOT EXISTS topic_follows (\n  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  topic   TEXT NOT NULL,\n  PRIMARY KEY (user_id, topic)\n);\n\n-- ---------------------------------------------------------------------------\n-- Thông báo nội bộ\n-- ---------------------------------------------------------------------------\nCREATE TABLE IF NOT EXISTS notifications (\n  id          TEXT PRIMARY KEY,\n  user_id     TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  kind        TEXT NOT NULL,\n  title       TEXT NOT NULL,\n  title_en    TEXT NOT NULL,\n  body        TEXT NOT NULL,\n  body_en     TEXT NOT NULL,\n  at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  read        BOOLEAN NOT NULL DEFAULT FALSE,\n  question_id TEXT\n);\n\n-- ---------------------------------------------------------------------------\n-- Báo cáo nội dung\n-- ---------------------------------------------------------------------------\nCREATE TABLE IF NOT EXISTS reports (\n  id          TEXT PRIMARY KEY,\n  user_id     TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  question_id TEXT NOT NULL REFERENCES questions(id) ON DELETE CASCADE,\n  answer_id   TEXT,\n  reason      TEXT NOT NULL,\n  detail      TEXT NOT NULL,\n  status      TEXT NOT NULL DEFAULT 'open',\n  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n\n-- ---------------------------------------------------------------------------\n-- Chỉ mục\n-- ---------------------------------------------------------------------------\nCREATE INDEX IF NOT EXISTS idx_answers_question ON answers(question_id);\nCREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id, read);\nCREATE INDEX IF NOT EXISTS idx_reports_status ON reports(status);\n\n-- Truy vấn danh sách câu hỏi luôn sắp theo thời điểm tạo.\nCREATE INDEX IF NOT EXISTS idx_questions_created ON questions(created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_questions_author ON questions(author_id);\nCREATE INDEX IF NOT EXISTS idx_questions_topic ON questions(topic);\nCREATE INDEX IF NOT EXISTS idx_answers_author ON answers(author_id);\nCREATE INDEX IF NOT EXISTS idx_answer_sources_answer ON answer_sources(answer_id);\n"
